{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "weaken",
  "supportive_card_ids": ["C05", "C24", "C08", "C14"],
  "contradictory_card_ids": ["C17", "C36", "C57", "C61", "C65", "C66", "C70", "C71", "C73"],
  "prediction_basis_card_ids": ["C05", "C24", "C08", "C14"],
  "claims": [
    {
      "claim": "KNI-272, the closest fed-state peptidomimetic context, had absolute oral bioavailability of 36.4% after a 6.6 mg/kg post-prandial capsule (n=2) and 22.06 ± 2.99% after a 4 mg/kg post-prandial capsule (n=5), both at or above the 20% threshold; the below-threshold 15.72 ± 5.96% value came from a 2 mg/kg cherry syrup, indicating dose/formulation dependence rather than a uniform low F.",
      "card_ids": ["C05", "C24", "C17"]
    },
    {
      "claim": "Atazanavir, a fed-state peptidomimetic HIV protease inhibitor with tert-butyl and hydroxyethyl motifs, has oral bioavailability >90% when taken with food, supporting high F for this chemical class under fed conditions.",
      "card_ids": ["C08", "C14"]
    },
    {
      "claim": "L6 hepatic-clearance records for saquinavir and indinavir are rat assays for different molecules; although saquinavir shows high intrinsic clearance in some assays (e.g., 112 ± 28 µL/min/mg protein media loss; 126 ± 36.5 µL/min/10^6 cells hepatocytes), estimates vary widely across studies and are not direct oral-bioavailability measurements for the query.",
      "card_ids": ["C66", "C70", "C71", "C73"]
    },
    {
      "claim": "Saquinavir P-gp efflux and low unboosted oral exposure are mechanism-level observations for a related molecule, not affirmative threshold-relevant evidence that the query has F < 20%.",
      "card_ids": ["C36", "C57", "C61", "C65"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C66", "C67", "C68", "C69", "C70", "C71", "C72", "C73", "C74", "C75", "C76", "C77"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the query molecule itself.",
    "Query dose and formulation are unspecified; KNI-272 fed F ranges from 15.72% (2 mg/kg syrup) to 36.4% (6.6 mg/kg capsule), so threshold classification could depend on formulation/dose.",
    "L6 hepatic clearance records are rat assays for saquinavir and indinavir, not the query; no query-specific metabolic stability or human clearance data are available.",
    "No query-specific P-gp/efflux, solubility, or permeability data are available.",
    "Atazanavir bioavailability report type is unspecified, and the KNI-272 36.4% value is based on n=2."
  ],
  "decision_summary": "High, moderate confidence: direct fed-state absolute F from the closest peptidomimetic contexts (KNI-272 post-prandial capsule F 22–36%; atazanavir >90% with food) supports F ≥ 20%; L6 saquinavir/indinavir hepatic clearance records are indirect rat mechanistic evidence that weakens but does not overturn the fed-state direct F evidence."
}

